// Real ECharts instance lifecycle, owned by one React effect and container.
// Dependency injection is only for deterministic lifecycle tests; App supplies
// the actual statically imported ECharts API in production.
export function headingChartOption(stats) {
  return {
    animation: false,
    grid: {left: 32, right: 28, top: 8, bottom: 28},
    xAxis: {type: 'value', min: 0, max: Math.max(1, stats.peak), minInterval: 1,
      axisLabel: {fontSize: 10, color: '#728095'}, splitLine: {lineStyle: {color: '#edf1f7'}}},
    yAxis: {type: 'category', inverse: true, data: stats.levels.map(row => 'H' + row.level),
      axisTick: {show: false}, axisLine: {show: false}, axisLabel: {fontSize: 11, color: '#728095'}},
    series: [{id: 'heading-levels', type: 'bar', data: stats.levels.map(row => row.count),
      barMaxWidth: 13, itemStyle: {color: '#4269d9', borderRadius: [0, 3, 3, 0]},
      label: {show: true, position: 'right', color: '#273247', fontSize: 11}}]
  };
}

export function mountHeadingChart({element, echarts, stats, onState = () => {},
  ResizeObserverClass = ResizeObserver, win = element.ownerDocument.defaultView}) {
  let stopped = false, instance = null, observer = null, frame = 0, latest = stats;
  let failed = false;
  function report(error) {
    if (stopped) return;
    failed = true;
    try { instance?.dispose(); } catch (cleanupError) {
      error = new Error(String(error?.message || error) + '；清理失败：' + String(cleanupError?.message || cleanupError));
    } finally { instance = null; }
    onState({status: 'error', message: '图表绘制失败：' + String(error?.message || error)});
  }
  function sync() {
    frame = 0;
    if (stopped || failed || !element.isConnected) return;
    const {width, height} = element.getBoundingClientRect();
    if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) return;
    try {
      if (!instance) {
        instance = echarts.init(element, null, {renderer: 'svg', width, height});
        instance.setOption(headingChartOption(latest), {notMerge: true, lazyUpdate: false});
      } else instance.resize({width, height});
      onState({status: 'ready', message: ''});
    } catch (error) { report(error); }
  }
  function schedule() {
    if (!stopped && !failed && !frame) frame = win.requestAnimationFrame(sync);
  }
  onState({status: 'loading', message: '正在绘制图表…'});
  try {
    observer = new ResizeObserverClass(schedule);
    observer.observe(element);
    schedule();
  } catch (error) { report(error); }
  return {
    update(next) {
      if (stopped || failed) return;
      latest = next;
      try {
        if (instance) instance.setOption(headingChartOption(latest), {notMerge: true, lazyUpdate: false});
        else schedule();
      } catch (error) { report(error); }
    },
    dispose() {
      if (stopped) return;
      stopped = true;
      observer?.disconnect();
      if (frame) win.cancelAnimationFrame(frame);
      frame = 0;
      try { instance?.dispose(); } finally { instance = null; }
    }
  };
}

// Pure chart model. App supplies the reviewed HTTPS ESM max import.
// The default is for isolated model tests, not automatic network fallback.
export function summarizeHeadingLevels(items, maxOf = values => Math.max(...values)) {
  const counts = [0, 0, 0, 0, 0, 0];
  for (const item of items || []) {
    if (Number.isInteger(item?.level) && item.level >= 1 && item.level <= 6) {
      counts[item.level - 1] += 1;
    }
  }
  const maximum = Number(maxOf(counts));
  const peak = Number.isFinite(maximum) && maximum > 0 ? maximum : 1;
  return {
    total: counts.reduce((sum, count) => sum + count, 0),
    peak,
    levels: counts.map((count, index) => ({
      level: index + 1, count, percent: Math.round(count / peak * 100)
    }))
  };
}

import {createElement, useEffect, useMemo, useRef, useState} from 'react';
import {chooseActiveTocItem, createTocScanner, sameToc, selectTocItems} from './toc-model.js';
import {summarizeHeadingLevels} from './heading-stats.js';
import max from 'https://raw.githubusercontent.com/d3/d3-array/v3.2.4/src/max.js';
import {init, use as useECharts} from 'https://cdn.jsdelivr.net/npm/echarts@5.6.0/core.js';
import {install as BarChart} from 'https://cdn.jsdelivr.net/npm/echarts@5.6.0/lib/chart/bar/install.js';
import {install as GridComponent} from 'https://cdn.jsdelivr.net/npm/echarts@5.6.0/lib/component/grid/install.js';
import {install as SVGRenderer} from 'https://cdn.jsdelivr.net/npm/echarts@5.6.0/lib/renderer/installSVGRenderer.js';
import {mountHeadingChart} from './heading-chart.js';

useECharts([BarChart, GridComponent, SVGRenderer]);
const echarts = {init};

// Official React JavaScript syntax. OpenDesk provides React, mounts this
// component in its managed Shadow DOM and runs root.unmount() on Stop.
// Real HTTPS ESM import above: the original project resolver verifies the
// checked-in lock/cache and links these bytes offline before Page execution.
// No @require, runtime import(), CDN script tag or extension-source edit.
const h = createElement;
const colors = {
  text: '#273247', muted: '#728095', line: '#e1e7f0', accent: '#4269d9',
  light: '#f1f5ff'
};
const ui = {
  card: {
    width: 'min(300px, calc(100vw - 32px))', maxWidth: '100%',
    background: '#fff', color: colors.text, border: '1px solid ' + colors.line,
    borderRadius: 13, boxShadow: '0 10px 32px rgba(17, 32, 57, 0.18)',
    padding: 11, font: '13px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif',
    colorScheme: 'light'
  },
  head: {display: 'flex', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'space-between', gap: 7},
  title: {fontWeight: 700, letterSpacing: '.06em', fontSize: 11, color: colors.muted},
  buttons: {display: 'flex', flexWrap: 'wrap', gap: 3, alignItems: 'center'},
  mode: {padding: '4px 6px', cursor: 'pointer', border: '1px solid transparent',
    borderRadius: 6, background: 'transparent', font: 'inherit', fontSize: 11,
    color: colors.muted},
  nav: {overflowY: 'auto', overscrollBehavior: 'contain', maxHeight: 'min(64vh, 520px)',
    marginTop: 10, scrollbarWidth: 'thin'},
  list: {display: 'grid', gap: 1, padding: 0, margin: 0, listStyle: 'none'},
  item: {display: 'block', width: '100%', border: 0, borderLeft: '2px solid transparent',
    background: 'transparent', color: '#5f6c80', textAlign: 'left', borderRadius: 4,
    paddingTop: 5, paddingBottom: 5, paddingRight: 5, cursor: 'pointer',
    lineHeight: 1.4, fontSize: 12, fontFamily: 'inherit', overflowWrap: 'anywhere'},
  footer: {display: 'flex', justifyContent: 'space-between', alignItems: 'center',
    gap: 6, marginTop: 8, paddingTop: 7, borderTop: '1px solid ' + colors.line,
    fontSize: 11, color: colors.muted},
  more: {border: 0, padding: 4, color: colors.accent, background: 'transparent',
    font: 'inherit', fontSize: 11, cursor: 'pointer'},
  empty: {padding: '10px 4px', color: colors.muted, fontSize: 12},
  status: {marginTop: 7, fontSize: 11, color: '#ad4a4f'},
  chart: {marginTop: 10, padding: '8px 4px 2px'},
  chartTitle: {margin: '0 0 9px', fontSize: 12, fontWeight: 650},
  chartContainer: {width: '100%', height: 208, minWidth: 0},
  chartSummary: {fontSize: 10, color: colors.muted, margin: '4px 0 0'}
};
const modes = [['overview', '概览'], ['focus', '当前'], ['full', '全部'], ['stats', '统计']];

function HeadingChart({stats}) {
  const container = useRef(null), chart = useRef(null);
  const [state, setState] = useState({status: 'loading', message: '正在绘制图表…'});
  useEffect(() => {
    const current = mountHeadingChart({element: container.current, echarts, stats, onState: setState});
    chart.current = current;
    return () => { chart.current = null; current.dispose(); };
  }, []);
  useEffect(() => { chart.current?.update(stats); }, [stats]);
  return h('div', {'data-echarts-state': state.status},
    h('div', {ref: container, style: ui.chartContainer, role: 'img',
      'aria-label': 'ECharts 标题层级分布，' + stats.levels.map(row => 'H' + row.level + '：' + row.count).join('，')}),
    h('p', {style: ui.chartSummary}, 'ECharts 5.6.0 · SVG · ' + stats.levels.map(row => 'H' + row.level + ' ' + row.count).join(' / ')),
    state.message && h('p', {role: state.status === 'error' ? 'alert' : 'status', style: ui.status}, state.message)
  );
}

export default function App() {
  const [items, setItems] = useState([]);
  const [activeId, setActiveId] = useState('');
  const [mode, setMode] = useState('focus');
  const [collapsed, setCollapsed] = useState(false);
  const [error, setError] = useState('');
  const scan = useMemo(() => createTocScanner(document), []);
  const currentItems = useRef([]);
  const stats = useMemo(() => summarizeHeadingLevels(items, max), [items]);

  useEffect(() => {
    const win = document.defaultView;
    let stopped = false, scanFrame = 0, activeFrame = 0;
    const refreshActive = () => {
      activeFrame = 0;
      if (stopped) return;
      const next = chooseActiveTocItem(currentItems.current);
      setActiveId(old => old === next ? old : next);
    };
    const rescan = () => {
      scanFrame = 0;
      if (stopped) return;
      try {
        const next = scan();
        currentItems.current = next;
        setItems(old => sameToc(old, next) ? old : next);
        setError('');
        refreshActive();
      } catch (reason) {
        setError('扫描目录失败：' + String(reason?.message || reason));
      }
    };
    const scheduleScan = () => {
      if (!stopped && !scanFrame) scanFrame = win.requestAnimationFrame(rescan);
    };
    const scheduleActive = () => {
      if (!stopped && !activeFrame) activeFrame = win.requestAnimationFrame(refreshActive);
    };
    // Shadow DOM changes from React are outside this observer's document subtree.
    const observer = new MutationObserver(scheduleScan);
    observer.observe(document.body || document.documentElement, {
      childList: true, subtree: true, characterData: true, attributes: true,
      attributeFilter: ['hidden', 'aria-hidden', 'style', 'class']
    });
    win.addEventListener('scroll', scheduleActive, true);
    win.addEventListener('resize', scheduleScan);
    win.addEventListener('hashchange', scheduleActive);
    scheduleScan();
    return () => {
      stopped = true;
      observer.disconnect();
      win.removeEventListener('scroll', scheduleActive, true);
      win.removeEventListener('resize', scheduleScan);
      win.removeEventListener('hashchange', scheduleActive);
      if (scanFrame) win.cancelAnimationFrame(scanFrame);
      if (activeFrame) win.cancelAnimationFrame(activeFrame);
    };
  }, [scan]);

  const shown = mode === 'stats' ? [] : selectTocItems(items, activeId, mode);
  function goTo(item) {
    if (!item.element?.isConnected) {
      setError('此章节已改变，请重新运行目录扫描。');
      return;
    }
    try {
      const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
      item.element.scrollIntoView({behavior: reducedMotion ? 'auto' : 'smooth', block: 'start'});
      setActiveId(item.id);
      setError('');
    } catch (reason) {
      setError('跳转失败：' + String(reason?.message || reason));
    }
  }
  return h('section', {style: ui.card, 'aria-label': 'React Direct 阅读目录演示'},
    h('header', {style: ui.head},
      h('strong', {style: ui.title}, 'CONTENTS'),
      h('div', {style: ui.buttons, role: 'group', 'aria-label': '目录视图'},
        ...(!collapsed ? modes.map(([value, label]) => h('button', {
          key: value, type: 'button', title: label, 'aria-label': label + '视图',
          'aria-pressed': mode === value,
          onClick: () => setMode(value),
          style: {...ui.mode, ...(mode === value ? {
            color: colors.accent, background: colors.light, borderColor: '#dce6ff'
          } : {})}
        }, label)) : []),
        h('button', {
          key: 'collapse', type: 'button', onClick: () => setCollapsed(value => !value),
          title: collapsed ? '展开目录' : '收起目录',
          'aria-label': collapsed ? '展开目录' : '收起目录',
          'aria-expanded': !collapsed,
          style: {...ui.mode, color: colors.text, fontSize: 14}
        }, collapsed ? '＋' : '－')
      )
    ),
    !collapsed && (mode === 'stats'
      ? h('section', {style: ui.chart, 'aria-label': '网页标题层级统计'},
        h('h3', {style: ui.chartTitle}, '标题层级分布 · ' + stats.total + ' 个'),
        h(HeadingChart, {stats})
      )
      : h('nav', {style: ui.nav, 'aria-label': '章节导航'},
      shown.length === 0
        ? h('p', {style: ui.empty}, '当前网页暂无可用正文标题')
        : h('ol', {style: ui.list}, ...shown.map(item => h('li', {key: item.id},
          h('button', {
            type: 'button', title: item.label,
            'aria-current': item.id === activeId ? 'location' : undefined,
            onClick: () => goTo(item),
            style: {...ui.item,
              paddingLeft: 8 + Math.min(item.depth, 3) * 11,
              ...(item.id === activeId ? {
                color: colors.text, fontWeight: 650,
                background: colors.light, borderLeftColor: colors.accent
              } : {})}
          }, item.label)
        ))))
    ),
    !collapsed && h('div', {style: ui.footer},
      h('span', null, items.length + ' 个章节 · React Direct Demo'),
      mode !== 'stats' && shown.length < items.length && h('button', {
        type: 'button', onClick: () => setMode('full'), style: ui.more
      }, '查看全部')
    ),
    !collapsed && error && h('p', {role: 'status', style: ui.status}, error)
  );
}

// Deliberately independent from the installed reading-toc tool. This is a
// page-local demo: read only real DOM headings and never modify page IDs/HTML.
const HEADING_SELECTOR = 'h1,h2,h3,h4,h5,h6';
const SKIP_SELECTOR = [
  'nav', 'aside', 'footer', 'pre', 'code', 'template', '[hidden]', '[inert]',
  '[aria-hidden="true"]', '[role="navigation"]', '[contenteditable="true"]',
  '[data-opendesk-ui-owner]'
].join(',');
const MAX_HEADINGS = 160;

function primaryContentRoot(doc) {
  // Prefer one meaningful article; otherwise use the page's main content.
  // Unlike the official tool, this small demo does not implement AI-answer
  // source switching or website-specific adapters.
  let best = null;
  let bestCount = 0;
  const roots = doc.querySelectorAll('main,[role="main"],article');
  for (const root of roots) {
    if (!root.isConnected || root.closest?.('[data-opendesk-ui-owner]')) continue;
    const count = root.querySelectorAll(HEADING_SELECTOR).length;
    const preferred = root.matches?.('article') ? 0.25 : 0;
    if (count + preferred > bestCount) {
      best = root;
      bestCount = count + preferred;
    }
  }
  return best || doc.body || doc.documentElement;
}

function visibleHeading(heading, doc) {
  if (!heading.isConnected || heading.closest?.(SKIP_SELECTOR)) return false;
  if (!heading.getClientRects?.().length) return false;
  const style = doc.defaultView?.getComputedStyle?.(heading);
  return !style || (style.display !== 'none' && style.visibility !== 'hidden');
}

// Pure model; separate from DOM lookup so it can be tested without a browser.
export function buildTocTree(rows) {
  const stack = [];
  return rows.map(row => {
    while (stack.length && stack[stack.length - 1].level >= row.level) stack.pop();
    const parent = stack[stack.length - 1];
    const item = {
      ...row,
      depth: stack.length,
      parentId: parent?.id || null,
      topId: parent?.topId || row.id
    };
    stack.push(item);
    return item;
  });
}

export function createTocScanner(doc) {
  const keys = new WeakMap();
  let serial = 0;
  return function scan() {
    const root = primaryContentRoot(doc);
    if (!root?.querySelectorAll) return [];
    const rows = [];
    for (const heading of root.querySelectorAll(HEADING_SELECTOR)) {
      if (rows.length >= MAX_HEADINGS) break;
      if (!visibleHeading(heading, doc)) continue;
      const label = (heading.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 160);
      if (!label) continue;
      let id = keys.get(heading);
      if (!id) {
        id = 'toc-demo-' + (++serial);
        keys.set(heading, id);
      }
      rows.push({id, element: heading, label, level: Number(heading.tagName.slice(1))});
    }
    return buildTocTree(rows);
  };
}

export function sameToc(a, b) {
  return a.length === b.length && a.every((item, i) =>
    item.id === b[i].id && item.element === b[i].element &&
    item.label === b[i].label && item.level === b[i].level &&
    item.depth === b[i].depth && item.parentId === b[i].parentId &&
    item.topId === b[i].topId);
}

export function chooseActiveTocItem(items, top = 112) {
  let passed = null;
  let next = null;
  for (const item of items) {
    if (!item.element?.isConnected) continue;
    const rect = item.element.getBoundingClientRect?.();
    if (!rect) continue;
    if (rect.top <= top) passed = item;
    else if (!next) next = item;
  }
  return passed?.id || next?.id || items[0]?.id || '';
}

function nearestPresentedId(items, choices, activeId) {
  const indexed = new Map(items.map(item => [item.id, item]));
  let item = indexed.get(activeId);
  while (item && !choices.has(item.id)) item = indexed.get(item.parentId);
  return item?.id || '';
}

function aroundActive(items, activeId, limit = 12) {
  if (items.length <= limit) return items;
  const activeIndex = Math.max(0, items.findIndex(item => item.id === activeId));
  const start = Math.max(0, Math.min(activeIndex - 5, items.length - limit));
  const segment = items.slice(start, start + limit);
  // Always keep the actual top-level heading in the compact view.
  if (segment[0] !== items[0]) return [items[0], ...segment.slice(1)];
  return segment;
}

// Small demo of three official-style views, not the official overview algorithm.
export function selectTocItems(items, activeId, mode = 'focus') {
  if (mode === 'full' || !items.length) return items;
  const active = items.find(item => item.id === activeId) || items[0];
  if (mode === 'focus') {
    const group = items.filter(item => item.topId === active.topId);
    return aroundActive(group, active.id);
  }
  const roots = items.filter(item => item.depth === 0);
  let candidates = roots;
  for (let depth = 1; candidates.length < 5 && depth <= 3; depth++) {
    const expanded = items.filter(item => item.depth <= depth);
    if (expanded.length === candidates.length) break;
    candidates = expanded;
  }
  const ids = new Set(candidates.map(item => item.id));
  const represented = nearestPresentedId(items, ids, active.id);
  return aroundActive(candidates, represented);
}
